#include <bits/stdc++.h>
using namespace std;

class Parser {
    string s; size_t p = 0;
public:
    Parser(string input): s(std::move(input)) {}
    void skip() {
        while (p < s.size() && (isspace((unsigned char)s[p]) || s[p] == ',')) ++p;
    }
    int readInt() {
        skip();
        if (p < s.size() && s[p] == '[') ++p;
        int sign = 1;
        if (s[p] == '-') { sign = -1; ++p; }
        int v = 0;
        while (p < s.size() && isdigit((unsigned char)s[p])) v = v * 10 + (s[p++] - '0');
        return sign * v;
    }
    vector<int> readArray() {
        skip();
        if (s[p++] != '[') throw runtime_error("bad input");
        skip();
        vector<int> a;
        if (s[p] == ']') { ++p; return a; }
        while (true) {
            a.push_back(readInt());
            skip();
            if (s[p] == ']') { ++p; break; }
        }
        return a;
    }
};

class Solution {
public:
    int getLastMoment(int n, vector<int>& left, vector<int>& right) {
        int ans = 0;
        for (int x : left) ans = max(ans, x);
        for (int x : right) ans = max(ans, n - x);
        return ans;
    }
};

