#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

typedef struct {
    const char *s;
    size_t p;
} Parser;

static void skip(Parser *p) {
    while (p->s[p->p] && (isspace((unsigned char)p->s[p->p]) || p->s[p->p] == ',' ||
                          p->s[p->p] == '[' || p->s[p->p] == ']')) {
        /* Do not skip closing brackets while reading arrays; handled by read_array. */
        if (p->s[p->p] == ']') break;
        p->p++;
    }
}

static int read_int(Parser *p) {
    skip(p);
    int sign = 1, v = 0;
    if (p->s[p->p] == '-') { sign = -1; p->p++; }
    while (isdigit((unsigned char)p->s[p->p])) {
        v = v * 10 + (p->s[p->p] - '0');
        p->p++;
    }
    return sign * v;
}

static int *read_array(Parser *p, int *size) {
    while (p->s[p->p] && p->s[p->p] != '[') p->p++;
    if (p->s[p->p] == '[') p->p++;
    int cap = 4, n = 0;
    int *a = (int*)malloc(cap * sizeof(int));
    while (1) {
        while (isspace((unsigned char)p->s[p->p]) || p->s[p->p] == ',') p->p++;
        if (p->s[p->p] == ']') { p->p++; break; }
        int x = read_int(p);
        if (n == cap) {
            cap *= 2;
            a = (int*)realloc(a, cap * sizeof(int));
        }
        a[n++] = x;
    }
    *size = n;
    return a;
}

static int getLastMoment(int n, const int *left, int nl, const int *right, int nr) {
    int ans = 0;
    for (int i = 0; i < nl; ++i) if (left[i] > ans) ans = left[i];
    for (int i = 0; i < nr; ++i) if (n - right[i] > ans) ans = n - right[i];
    return ans;
}

