public class Main {
    static class Parser {
        String s; int p = 0;
        Parser(String s) { this.s = s; }
        void skip() {
            while (p < s.length() && (Character.isWhitespace(s.charAt(p)) || s.charAt(p) == ',')) p++;
        }
        int readInt() {
            skip();
            int sign = 1;
            if (s.charAt(p) == '-') { sign = -1; p++; }
            int v = 0;
            while (p < s.length() && Character.isDigit(s.charAt(p))) v = v * 10 + (s.charAt(p++) - '0');
            return sign * v;
        }
        int[] readArray() {
            skip();
            if (s.charAt(p++) != '[') throw new IllegalArgumentException();
            skip();
            if (s.charAt(p) == ']') { p++; return new int[0]; }
            ArrayList<Integer> a = new ArrayList<>();
            while (true) {
                a.add(readInt());
                skip();
                if (s.charAt(p) == ']') { p++; break; }
            }
            int[] r = new int[a.size()];
            for (int i = 0; i < r.length; i++) r[i] = a.get(i);
            return r;
        }
